import assert from 'node:assert/strict';

import { bookingHistory } from '../src/projections/history.ts';
import type { DomainEvent } from '../src/domain/events.ts';

describe('ประวัติเหตุการณ์ของการจอง (REQ-41)', () => {
  test('คืนเฉพาะเหตุการณ์ของการจองที่ร้องขอ', () => {
    const events = [
      { type: 'BookingRequested', bookingId: 'bk-1', occurredAt: '2026-05-01T09:00:00.000Z', actorId: 'u-pat', userId: 'u-pat', userRole: 'STUDENT', resourceId: 'gpu-a100-01', startAt: '2026-05-01T10:00:00.000Z', endAt: '2026-05-01T12:00:00.000Z', requiresApproval: false },
      { type: 'BookingRequested', bookingId: 'bk-2', occurredAt: '2026-05-01T09:05:00.000Z', actorId: 'u-mo', userId: 'u-mo', userRole: 'STUDENT', resourceId: 'gpu-v100-01', startAt: '2026-05-01T13:00:00.000Z', endAt: '2026-05-01T14:00:00.000Z', requiresApproval: false },
    ] as DomainEvent[];

    const result = bookingHistory(events, 'bk-1');
    assert.equal(result.length, 1);
    assert.equal(result[0].bookingId, 'bk-1');
  });

  test('คืนเหตุการณ์เรียงตามเวลาที่เกิดขึ้น แม้บันทึกไว้ไม่เรียง', () => {
    const events = [
      { type: 'BookingCompleted', bookingId: 'bk-1', occurredAt: '2026-05-01T12:00:00.000Z', actorId: 'u-pat', actualEndAt: '2026-05-01T12:00:00.000Z' },
      { type: 'BookingRequested', bookingId: 'bk-1', occurredAt: '2026-05-01T09:00:00.000Z', actorId: 'u-pat', userId: 'u-pat', userRole: 'STUDENT', resourceId: 'gpu-a100-01', startAt: '2026-05-01T10:00:00.000Z', endAt: '2026-05-01T12:00:00.000Z', requiresApproval: false },
